/// One non-padding input field of the surface ABI.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SurfaceFieldLayout {
    /// `None` for the always-present core, otherwise the schema lobe id.
    pub lobe: Option<&'static str>,
    /// Field name within the owning record.
    pub name: &'static str,
    /// Target member in the decoded CPU/GPU fat surface.
    pub surface_field: &'static str,
    /// Exact schema storage type (`f32`, `vec4f`, or `f16`).
    pub storage_type: &'static str,
    /// First `u32` word within the owning record.
    pub pack_slot: u32,
    /// Word footprint of the field's storage type.
    pub words: u32,
    /// Schema bit-region spelling (`KHR`, `PRISM`, ...).
    pub bit_region: &'static str,
    /// Declared pipeline consumers, in schema order.
    pub consumed_by: &'static [&'static str],
}

